from pathlib import Path
import base64
import json
import re
import zlib

# ORIVECTOR review PDF v1 question bank (250 questions), compressed JSON.
# The payload is intentionally embedded so the site update is deterministic and auditable.
PAYLOAD = ''''''

raw = zlib.decompress(base64.b64decode(PAYLOAD)).decode('utf-8')
questions = json.loads(raw)

if len(questions) != 250:
    raise SystemExit(f'Safety stop: expected 250 questions, got {len(questions)}')
if len({q[0] for q in questions}) != 250:
    raise SystemExit('Safety stop: duplicate question stems detected')
if any(len(q) != 5 or len(q[1]) != 4 or q[2] not in range(4) for q in questions):
    raise SystemExit('Safety stop: malformed question data')

# Normalize PDF review domain labels to the site's existing category labels.
for q in questions:
    q[4] = {
        '1. クラウドのコンセプト': 'クラウドの概念',
        '2. セキュリティとコンプライアンス': 'セキュリティとコンプライアンス',
        '3. クラウドテクノロジーとサービス': 'クラウドテクノロジーとサービス',
        '4. 請求、料金、サポート': '請求、料金、サポート',
    }.get(q[4], q[4])

index_path = Path('index.html')
html = index_path.read_text(encoding='utf-8')

start_marker = 'const questions='
end_marker = ';\nconst defaultData='
start = html.find(start_marker)
end = html.find(end_marker, start)
if start < 0 or end < 0:
    raise SystemExit('Safety stop: question bank markers not found')

new_js = json.dumps(questions, ensure_ascii=False, separators=(',', ':'))
html = html[:start] + start_marker + new_js + html[end:]

# Version bump only if the current expected version is present.
if 'ver 4.0.0' in html:
    html = html.replace('ver 4.0.0', 'ver 4.1.0', 1)
elif 'ver 4.1.0' not in html:
    raise SystemExit('Safety stop: unexpected site version; refusing blind version rewrite')

# Final guards before writing.
if html.count('const questions=') != 1:
    raise SystemExit('Safety stop: unexpected questions declaration count')
if 'const maxExamQuestions=' not in html:
    raise SystemExit('Safety stop: MAX exam bank unexpectedly missing')
if 'function startWrong' not in html or 'function showQuestionList' not in html:
    raise SystemExit('Safety stop: core quiz functions unexpectedly missing')

index_path.write_text(html, encoding='utf-8')
print('Applied reviewed reference-style CLF-C02 question bank: 250 questions')
print('Version: 4.1.0')
